import sys
from math import prod

class Solution:
    def abbreviateProduct(self, left: int, right: int) -> str:
        try:
            sys.set_int_max_str_digits(0)
        except AttributeError:
            pass
        c2 = 0
        c5 = 0
        for n in range(left, right + 1):
            x = n
            while x % 2 == 0:
                x //= 2
                c2 += 1
            x = n
            while x % 5 == 0:
                x //= 5
                c5 += 1
        C = min(c2, c5)
        p = prod(range(left, right + 1))
        p //= 10 ** C
        s = str(p)
        if len(s) <= 10:
            return s + "e" + str(C)
        return s[:5] + "..." + s[-5:] + "e" + str(C)
```

