Use a breadth-first search that records each node's depth and parent. When both x and y have been found, they are cousins if their depths match and their parents differ.

```python
from collections import deque
from typing import Optional

class Solution:
    def isCousins(self, root: Optional['TreeNode'], x: int, y: int) -> bool:
        info = {}
        q = deque([(root, None, 0)])
        while q:
            node, parent, depth = q.popleft()
            if node.val == x or node.val == y:
                info[node.val] = (parent, depth)
                if len(info) == 2:
                    break
            if node.left:
                q.append((node.left, node, depth + 1))
            if node.right:
                q.append((node.right, node, depth + 1))
        if x not in info or y not in info:
            return False
        px, dx = info[x]
        py, dy = info[y]
        return dx == dy and px is not py
```

