from typing import List

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        n = len(bloomDay)
        if m * k > n:
            return -1

        def ok(d):
            cnt = 0
            run = 0
            for b in bloomDay:
                if b <= d:
                    run += 1
                    if run == k:
                        cnt += 1
                        run = 0
                        if cnt >= m:
                            return True
                else:
                    run = 0
            return cnt >= m

        lo, hi = min(bloomDay), max(bloomDay)
        while lo < hi:
            mid = (lo + hi) // 2
            if ok(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
```

