Use a union-find structure. For each request, find the roots of u and v. If the roots are equal, the request succeeds. Otherwise, check every restriction (x, y): if the roots of x and y are the same as the roots of u and v, in either order, the request fails. If no restriction blocks it, union u and v and mark the request as successful.

The cost is O(requests × restrictions), about 10^6 find operations, which is fine.

```python
from typing import List

class Solution:
    def friendRequests(self, n: int, restrictions: List[List[int]], requests: List[List[int]]) -> List[bool]:
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        res = []
        for u, v in requests:
            pu, pv = find(u), find(v)
            if pu == pv:
                res.append(True)
                continue
            ok = True
            for x, y in restrictions:
                px, py = find(x), find(y)
                if (px == pu and py == pv) or (px == pv and py == pu):
                    ok = False
                    break
            if ok:
                parent[pu] = pv
            res.append(ok)
        return res
