from typing import List

class Solution:
    def removeInvalidParentheses(self, s: str) -> List[str]:
        l = r = 0
        for c in s:
            if c == '(':
                l += 1
            elif c == ')':
                if l > 0:
                    l -= 1
                else:
                    r += 1
        res = set()
        n = len(s)

        def dfs(i, bal, l, r, path):
            if l < 0 or r < 0:
                return
            if i == n:
                if l == 0 and r == 0 and bal == 0:
                    res.add("".join(path))
                return
            if n - i < l + r:
                return
            c = s[i]
            if c == '(':
                if l > 0:
                    dfs(i + 1, bal, l - 1, r, path)
                path.append(c)
                dfs(i + 1, bal + 1, l, r, path)
                path.pop()
            elif c == ')':
                if r > 0:
                    dfs(i + 1, bal, l, r - 1, path)
                if bal > 0:
                    path.append(c)
                    dfs(i + 1, bal - 1, l, r, path)
                    path.pop()
            else:
                path.append(c)
                dfs(i + 1, bal, l, r, path)
                path.pop()

        dfs(0, 0, l, r, [])
        return list(res)
