from itertools import permutations

class Solution:
    def nextBeautifulNumber(self, n: int) -> int:
        best = None
        for mask in range(1, 1 << 7):
            digs = []
            s = 0
            for d in range(1, 8):
                if mask >> (d - 1) & 1:
                    s += d
                    digs.extend([d] * d)
            if s > 7:
                continue
            for p in set(permutations(digs)):
                v = int("".join(map(str, p)))
                if v > n and (best is None or v < best):
                    best = v
