from typing import List

class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        lo, hi = max(nums), sum(nums)

        def need(limit):
            cnt = 1
            cur = 0
            for x in nums:
                if cur + x > limit:
                    cnt += 1
                    cur = x
                else:
                    cur += x
            return cnt

        while lo < hi:
            mid = (lo + hi) // 2
            if need(mid) <= k:
                hi = mid
            else:
                lo = mid + 1
