Approach: split each cell into 4 triangles (0=top, 1=right, 2=bottom, 3=left) and merge them with union-find.

- For a blank cell, union all 4 triangles.
- For `/`, union top with left (0, 3) and bottom with right (2, 1).
- For `\`, union top with right (0, 1) and bottom with left (2, 3).
- Between cells, union the bottom triangle of (i, j) with the top triangle of (i+1, j), and the right triangle of (i, j) with the left triangle of (i, j+1).

The answer is the number of connected components.

```python
from typing import List

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        parent = list(range(4 * n * n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for i in range(n):
            for j in range(n):
                base = 4 * (i * n + j)
                c = grid[i][j]
                if c == ' ':
                    union(base, base + 1)
                    union(base, base + 2)
                    union(base, base + 3)
                elif c == '/':
                    union(base, base + 3)
                    union(base + 1, base + 2)
                else:
                    union(base, base + 1)
                    union(base + 2, base + 3)
                if i + 1 < n:
                    union(base + 2, 4 * ((i + 1) * n + j))
                if j + 1 < n:
                    union(base + 1, 4 * (i * n + j + 1) + 3)

        return sum(1 for x in range(4 * n * n) if find(x) == x)
```

